mapper.insert:
INSERT INTO practice_attempt(
    practice_item_id, answer, self_score, result, feedback, attempted_at
)
VALUES(
    #{practiceItemId}, #{answer}, #{selfScore}, #{result}, #{feedback}, #{attemptedAt}
)

mapper.select:
SELECT COUNT(*)
FROM practice_attempt
WHERE practice_item_id = #{itemId}

SELECT MAX(a.attempted_at)
FROM practice_attempt a
JOIN practice_item i ON i.id = a.practice_item_id
WHERE i.user_id = #{userId}

    AND i.archived = #{archived}
